"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[2328],{92328:e=>{e.exports=JSON.parse('{"meta":{"title":"Niyyah : faire d\u2019une intention un petit pas r\xe9gulier - iMuslim Life","description":"Niyyah transforme une intention en plan de 7 jours ancr\xe9 dans vos heures de pri\xe8re, et \xc9chos du Coran trouve des passages du Coran valid\xe9s par des savants pour ce que vous avez sur le c\u0153ur. Gratuit, sans publicit\xe9."},"periods":{"fajr":"Fajr","dhuhr":"Dhuhr","asr":"Asr","maghrib":"Maghrib","isha":"Isha"},"hero":{"eyebrow":"Niyyah","h1":"Faites d\u2019une intention un pas <g>petit et r\xe9gulier</g>.","lede":"Cinq questions douces deviennent un plan de sept jours tiss\xe9 dans les pri\xe8res que vous accomplissez d\xe9j\xe0. Et quand votre c\u0153ur est lourd, \xc9chos du Coran trouve les versets qui lui parlent.","begin":"Commencer, bismillah","tryEchoes":"Essayer \xc9chos du Coran","facts":"Gratuit \xb7 Sans publicit\xe9 \xb7 Valid\xe9 par des savants \xb7 Dans votre navigateur","scroll":"Faites d\xe9filer : une journ\xe9e, de Fajr \xe0 Isha","alt":"Niyyah : un mihrab avec la Basmala sous le ciel nocturne"},"hadith":{"text":"\xab Les actes ne valent que par les intentions. \xbb","src":"Sahih al-Bukhari 1 \xb7 Sahih Muslim 1907"},"steps":[{"t":"Intention","d":"Choisissez ce en quoi vous voulez grandir : la patience, la proximit\xe9 du Coran, la gratitude, la douceur au foyer."},{"t":"Action","d":"Un petit pas de deux \xe0 quinze minutes. Assez petit pour le tenir m\xeame dans votre journ\xe9e la plus difficile."},{"t":"Moment","d":"Rattach\xe9 \xe0 une pri\xe8re que vous accomplissez d\xe9j\xe0, \xe0 vos propres heures de pri\xe8re, il suit les saisons."},{"t":"R\xe9flexion","d":"Un point en douceur au troisi\xe8me et au septi\xe8me jour. Mauvais moment ? Trop charg\xe9 ? Cela s\u2019ajuste en quelques secondes."}],"effortNote":"Accomplir une routine est un effort de notre part. L\u2019acceptation et les fruits appartiennent \xe0 Allah. Le plan est un outil, pas une mesure de votre foi.","try":{"eyebrow":"\xc9chos du Coran \xb7 essayez maintenant","h2":"Qu\u2019avez-vous sur le <e>c\u0153ur</e> ?","lede":"\xc9crivez une ligne sur ce que vous traversez, en anglais, en ourdou, en ourdou romanis\xe9 ou en arabe. Niyyah r\xe9pond par un passage tir\xe9 d\u2019un index valid\xe9 par des savants et une question \xe0 m\xe9diter. Sans connexion. Rien de ce que vous \xe9crivez n\u2019est enregistr\xe9.","inputLabel":"D\xe9crivez votre situation","listening":"\xc9coute\u2026","find":"Trouver des passages","failed":"\xc9chos du Coran est injoignable pour le moment. Il se trouve sur <a>alexa.imuslimlife.com/niyyah</a>, essayez l\xe0-bas.","crisisH":"Parlez \xe0 quelqu\u2019un d\xe8s maintenant, s\u2019il vous pla\xeet.","crisisP":"Ce que vous d\xe9crivez semble grave, et vous m\xe9ritez le vrai soutien d\u2019une personne.","rulingEyebrow":"Cela rel\xe8ve d\u2019un savant","rulingH":"Les questions de jugement religieux demandent une personne qualifi\xe9e.","rulingP":"Niyyah ne donne jamais de fatwa. Un imam qui conna\xeet votre situation pourra vous r\xe9pondre correctement.","none":"Pas encore de correspondance proche. Ajoutez quelques mots sur ce que vous ressentez ou traversez.","surah":"Sourate","tafsir":"Tafsir","plan":"En faire un plan de 7 jours","missThanks":"Merci, cela nous aide \xe0 nous am\xe9liorer. Essayez de le d\xe9crire autrement.","miss":"Ce n\u2019est pas ce que je voulais dire","shared":"Partag\xe9, merci. Cela aide \xe0 am\xe9liorer \xc9chos du Coran.","share":"Partager cette question (sans votre nom) pour aider \xe0 am\xe9liorer \xc9chos du Coran.","example":"Un exemple","exampleQ":"Quand le rappel d\u2019Allah vous a-t-il apais\xe9 pour la derni\xe8re fois ?","exampleSrc":"Ar-Ra\u2019d 13:28 \xb7 Traduction du sens : Muhammad Hamidullah. Arabe : Tanzil Uthmani.","examples":["I keep losing my temper with my kids","mujhe bohat ghussa aata hai","I feel guilty, will Allah forgive me?","My father passed away and it feels heavy","I\u2019m anxious about money and the future"],"placeholder":"For example: I get impatient with my children in the evenings"},"ayah":{"en":"ceux qui ont cru, et dont les c\u0153urs se tranquillisent \xe0 l\'\xe9vocation d\'Allah\xbb. Certes, c\'est par l\'\xe9vocation d\'Allah que les c\u0153urs se tranquillisent.","src":"Ar-Ra\u2019d 13:28 \xb7 Traduction du sens : Muhammad Hamidullah"},"week":{"eyebrow":"Votre semaine","h2":"Chaque jour o\xf9 vous \xeates pr\xe9sent, <e>une rose s\u2019ouvre</e>.","lede":"Pas de s\xe9rie \xe0 briser, pas de culpabilit\xe9. Les jours manqu\xe9s restent simplement des boutons ferm\xe9s, et le plan reprend demain. Le ciel change avec vos heures de pri\xe8re, du rose de Fajr aux \xe9toiles d\u2019Isha.","label":"Une semaine de roses : cinq jours ouverts","shots":["Aujourd\u2019hui, \xe0 Isha","Votre plan de 7 jours","Le m\xeame jour, \xe0 Dhuhr"]},"care":{"eyebrow":"Con\xe7u avec soin","h2":"Digne de confiance <e>par conception</e>.","items":[{"t":"Valid\xe9 par des savants","d":"Chaque passage, petite action et question est relu et approuv\xe9 avant que quiconque ne le voie."},{"t":"Jamais de fatwa","d":"Les questions de jugement sont orient\xe9es avec douceur vers un savant qualifi\xe9. Niyyah ne statue jamais."},{"t":"Rien d\u2019invent\xe9","d":"Aucune IA n\u2019\xe9crit de texte religieux ici. Les passages sont le Coran lui-m\xeame, avec une traduction nomm\xe9e."},{"t":"S\xfbr","d":"Les mots \xe9voquant un danger affichent d\u2019abord des lignes d\u2019\xe9coute, jamais des passages."},{"t":"Priv\xe9","d":"Vos notes n\u2019appartiennent qu\u2019\xe0 vous. Effacez tout d\u2019un geste."},{"t":"Gratuit, pour toujours","d":"Sans publicit\xe9 ni abonnement. Une sadaqa jariya, in sh\u0101\u02be All\u0101h."}]},"faq":{"eyebrow":"Questions","h2":"Bon \xe0 <e>savoir</e>.","items":[{"q":"Que signifie \xab Niyyah \xbb ?","a":"La niyya (\u0646\u0650\u064a\u064e\u0651\u0629) est l\u2019intention. \xab Les actes ne valent que par les intentions \xbb (Sahih al-Bukhari 1). Niyyah aide une intention \xe0 devenir une action petite et r\xe9guli\xe8re."},{"q":"Ai-je besoin d\u2019un compte ?","a":"Aucun compte n\u2019est n\xe9cessaire pour essayer \xc9chos du Coran. Pour garder un plan, marquer vos jours et enregistrer des passages, connectez-vous avec Amazon, la m\xeame connexion que Muslim Companion for Alexa."},{"q":"Quelles langues comprend-il ?","a":"L\u2019anglais, l\u2019ourdou, l\u2019ourdou romanis\xe9 (comme \xab mujhe bohat ghussa aata hai \xbb) et l\u2019arabe. Les passages affichent l\u2019arabe avec une traduction anglaise ou ourdoue."},{"q":"Remplace-t-il un savant ou un conseiller ?","a":"Non. Niyyah propose des passages \xe0 m\xe9diter et de petits pas \xe0 faire. Pour les jugements, interrogez un savant qualifi\xe9 ; dans les moments difficiles, tournez-vous vers une personne de confiance ou une ligne d\u2019\xe9coute."},{"q":"O\xf9 fonctionne-t-il ?","a":"Dans tout navigateur sur t\xe9l\xe9phone, tablette ou ordinateur, \xe0 l\u2019adresse alexa.imuslimlife.com/niyyah."}]},"final":{"h2":"Commencez par un <g>petit</g> pas.","lede":"Votre premier plan prend une minute. Qu\u2019Allah vous le facilite et l\u2019accepte de vous.","alexa":"Muslim Companion for Alexa"}}')}}]);